"""RoboPaint: camera-calibrated brush motion for Vermeer's portrait.
Only the public Robot client, RGB/depth observations, and proprioception are used.
"""
import sys, json, time, math
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
ROOT=Path('/app/output')

class Painter:
    def __init__(self):
        self.r=Robot(); self.spec=self.r.spec()
        self.obs=self.r.get_obs(cameras=[])
        self.pose=np.array(self.obs.meta['proprio']['now'][7:14]);self.quat=self.pose[3:].copy()
        self.calls=0
    def send(self, poses, dt=.05, cameras=(), note=''):
        poses=np.asarray(poses)
        for i in range(0,len(poses),200):
            part=poses[i:i+200]
            before=self.r.status()
            try:
                result=self.r.submit('ee_pose',part,dt=dt,cameras=list(cameras),video='none',note=note)
            except Exception:
                status=self.r.wait_ready()
                if status['control_steps']==before['control_steps']:
                    result=self.r.submit('ee_pose',part,dt=dt,cameras=list(cameras),video='none',note=note)
                else:
                    result=self.r.get_obs(cameras=list(cameras))
            self.pose=np.array(result.meta['proprio']['now'][7:14]); self.calls+=1
            Path('/app/output/current.json').write_text(json.dumps(result.meta))
            for cam,img in result.last.items():Image.fromarray(img).save(ROOT/(cam+'.png'))
            if result.meta.get('plan'):print('PLAN',result.meta['plan'],flush=True)
            if result.done:raise RuntimeError('Episode ended: '+str(result.meta.get('reason')))
        return result
    def path(self, xyz, speed=.06, dwell=.3, cameras=(),note=''):
        points=[];prev=self.pose[:3].copy()
        for point in xyz:
            point=np.asarray(point)
            n=max(1,int(np.ceil(np.linalg.norm(point-prev)/(speed*.05))))
            for a in np.linspace(0,1,n+1)[1:]:points.append(np.r_[prev*(1-a)+point*a,self.quat])
            prev=point
        points.extend([np.r_[prev,self.quat]]*round(dwell/.05))
        return self.send(points,cameras=cameras,note=note)
    def park(self):return self.path([[-.27,0,.17]],cameras=['canvas_cam','practice_cam','scene_cam'],note='Park for unobstructed cameras')

if __name__=='__main__':
    p=Painter(); p.park()
    o=p.r.get_obs(cameras=['scene_cam','canvas_cam','practice_cam'],depth=True);o.save('/app/runs/parked')
    print(p.r.status(),flush=True)
PY
